async function openEconomy(){try{const r=await sb.functions.invoke("public-experience",{body:{action:"economy_list",territory_id:territoryForArea()}});if(r.error||!r.data?.ok)throw new Error(r.data?.error||r.error?.message||"Gagal memuat ekonomi desa");const x=r.data;openModal("<span class='eyebrow dark'>EKONOMI DESA</span><h2 class='modal-title'>Potensi lokal menjadi <em>nilai.</em></h2><p class='modal-copy'>Direktori hanya menampilkan profil usaha yang ditandai dapat dipublikasikan. Data pribadi pemilik tidak ditampilkan.</p><div class='economy-live-grid'><div><small>PELAKU USAHA</small><strong>"+x.stats.businesses+"</strong><span>profil usaha publik</span></div><div><small>PRODUK & JASA</small><strong>"+x.stats.products+"</strong><span>entri produk/jasa</span></div><div><small>SEKTOR</small><strong>"+x.stats.sectors+"</strong><span>sektor usaha</span></div></div><div class='tracking-list'>"+(x.records.length?x.records.map(b=>"<div class='tracking-row'><strong>"+b.business_name+"</strong><span>"+(b.sector||b.business_type||"Usaha lokal")+"</span><small>"+(b.products_services||"Produk/jasa lokal")+"</small></div>").join(""):"<div class='modal-note'>Belum ada profil usaha publik.</div>")+"</div><div class='modal-cta submenu-actions'><button class='btn btn-civic' data-economy-register>Daftarkan usaha</button><button class='btn btn-outline-civic' data-menu-main>Menu utama</button><button class='btn btn-outline-civic' data-home>Home</button></div>")}catch(x){showToast("Gagal memuat Ekonomi Desa: "+(x?.message||"kesalahan"))}}function loginRequired(){openModal('<span class="eyebrow dark">AKUN WARGA</span><h2 class="modal-title">Masuk ke SIM RT/RW</h2><p class="modal-copy">Untuk mengirim formulir resmi, silakan masuk terlebih dahulu melalui aplikasi SIM RT/RW–SID. Setelah login, kembali ke website ini pada perangkat yang sama.</p><div class="login-choice"><a class="btn btn-civic" href="../">Buka SIM RT/RW</a><button class="btn btn-outline-civic" data-close-modal>Tutup</button></div><div class="modal-note mt-3"><i class="bi bi-shield-check"></i> Sesi autentikasi menggunakan Supabase Auth yang sama.</div>')}
function openBusinessRegistration(){const uPromise=currentUser();uPromise.then(u=>{if(!u){loginRequired();return}openModal(`<span class="eyebrow dark">REGISTRASI USAHA DESA</span><h2 class="modal-title">Daftarkan <em>usaha Anda.</em></h2><p class="modal-copy">Profil akan masuk sebagai data internal dan menunggu verifikasi desa. Profil tidak otomatis tampil di direktori publik.</p><form id="businessRegisterForm" class="form-preview"><label>Nama usaha<input name="business_name" required></label><label>Jenis usaha<input name="business_type" placeholder="Contoh: Kuliner, perdagangan, jasa" required></label><label>Sektor usaha<input name="sector" placeholder="Contoh: Makanan & minuman"></label><label>Produk / jasa<textarea name="products_services" required></textarea></label><label>Skala usaha<select name="scale"><option value="">Pilih</option><option>MIKRO</option><option>KECIL</option><option>MENENGAH</option><option>LAINNYA</option></select></label><label>Jumlah pekerja<input name="worker_count" type="number" min="0" value="0"></label><label>Saluran penjualan<input name="sales_channels" placeholder="Contoh: Toko, WhatsApp, marketplace"></label><label>Status perizinan<input name="licensing_status" placeholder="Contoh: NIB / proses / belum ada"></label><label>Kebutuhan usaha<textarea name="needs"></textarea></label><label>Kendala usaha<textarea name="constraints"></textarea></label><label>Potensi / rencana pengembangan<textarea name="potential"></textarea></label><label>Wilayah aktif<input value="${areas[currentArea()].label}" disabled></label><div class="form-note"><i class="bi bi-shield-check"></i> Data pribadi pemilik tidak ditampilkan pada direktori publik. Publikasi dilakukan setelah verifikasi.</div><div class="form-nav"><button class="btn btn-civic" type="submit"><i class="bi bi-shop me-1"></i>Kirim registrasi usaha</button><button class="btn btn-outline-civic" type="button" data-economy-back> Kembali</button><button class="btn btn-outline-civic" type="button" data-home>Home</button></div><div id="businessRegisterError" class="form-error" role="alert"></div></form>`);document.getElementById("businessRegisterForm")?.addEventListener("submit",async e=>{e.preventDefault();const err=document.getElementById("businessRegisterError");try{const payload=Object.fromEntries(new FormData(e.target).entries());const r=await sb.functions.invoke("public-service-request",{body:{action:"business_register",territory_id:territoryForArea(),payload}});if(r.error||!r.data?.ok)throw new Error(r.data?.error||r.error?.message||"Registrasi usaha gagal");closeModal();showToast("✓ Profil usaha tersimpan dan menunggu verifikasi desa.");}catch(x){if(err)err.textContent=x?.message||"Registrasi usaha gagal";}})}).catch(()=>loginRequired())}function territoryForArea(){return "f06b8420-54f5-4ee4-b487-bacc7b374dd2"}
