function fieldHtml(f){const [name,label,type,required,options]=f;if(type==="textarea")return `<label>${label}<textarea name="${name}" ${required?"required":""}></textarea></label>`;if(type==="select")return `<label>${label}<select name="${name}" ${required?"required":""}>${options.map(o=>`<option>${o}</option>`).join("")}</select></label>`;return `<label>${label}<input name="${name}" type="${type}" ${required?"required":""}></label>`}
function publicForm(key){const d=formDefs[key];if(!d)return;openModal(`<span class="eyebrow dark">FORMULIR LAYANAN</span><h2 class="modal-title">${d.title}</h2><p class="modal-copy">Data ini dikirim ke SIM RT/RW–SID sebagai permohonan <strong>${d.service}</strong>. Untuk KK, sumber pengajuan menggunakan F-1.02 dan hasilnya dipetakan ke F-1.09 setelah proses berwenang.</p><form id="svServiceForm" class="form-preview">${d.fields.map(fieldHtml).join("")}<label>Wilayah aktif<input value="${areas[currentArea()].label}" disabled></label><div class="form-note"><i class="bi bi-info-circle"></i> Pastikan data sudah benar sebelum dikirim. Data akan masuk ke SIM RT/RW–SID untuk diproses sesuai alur layanan.</div><div class="form-nav"><button class="btn btn-civic" type="submit"><i class="bi bi-send me-1"></i>Kirim pengajuan resmi</button><button class="btn btn-outline-civic" type="button" data-form-back="${key}"><i class="bi bi-arrow-left me-1"></i>Kembali</button><button class="btn btn-outline-civic" type="button" data-form-menu="${key}"><i class="bi bi-grid me-1"></i>Menu layanan</button><button class="btn btn-outline-civic" type="button" data-home><i class="bi bi-house me-1"></i>Home</button></div><div class="form-note"><i class="bi bi-shield-check"></i> Website tidak menerbitkan dokumen pemerintah. Permohonan masuk ke alur verifikasi dan proses berwenang.</div><div id="svFormError" class="form-error" role="alert"></div></form>`);document.getElementById("svServiceForm")?.addEventListener("submit",async e=>{e.preventDefault();try{const user=await currentUser();if(!user){loginRequired();return}const payload=Object.fromEntries(new FormData(e.target).entries());if(d.service==="HOUSEHOLD"){payload.request_kk=payload.request_type==="KK Baru";payload.members=payload.members.split(/\n|,/).map(x=>({full_name:x.trim()})).filter(x=>x.full_name)}const resp=await sb.functions.invoke("public-service-request",{body:{service_type:d.service,territory_id:territoryForArea(),payload}});if(resp.error||!resp.data?.ok)throw new Error(resp.data?.error||resp.error?.message||"Pengajuan gagal");closeModal();showToast("✓ Pengajuan masuk ke SIM RT/RW · "+(resp.data.record?.request_number||resp.data.record?.id||"tersimpan"));}catch(x){document.getElementById("svFormError").textContent=x?.message||"Pengajuan gagal";}})}
function startService(key,index){if(key==="tracking"){openTracking();return}if(index!=null){const formKey=key+":"+index;if(!formDefs[formKey]){showToast("Formulir layanan belum tersedia untuk pilihan ini.");return}currentUser().then(u=>{if(u)publicForm(formKey);else loginRequired()}).catch(()=>loginRequired());return}const firstFormKey=key+":0";if(formDefs[firstFormKey]){currentUser().then(u=>{if(u)publicForm(firstFormKey);else loginRequired()}).catch(()=>loginRequired());return}serviceModal(key)}
async function openTracking(){try{const u=await currentUser();if(!u){loginRequired();return}const resp=await sb.functions.invoke("public-service-request",{body:{action:"list"}});if(resp.error||!resp.data?.ok)throw new Error(resp.data?.error||resp.error?.message||"Gagal mengambil permohonan");const rows=resp.data.records||[];openModal(`<span class="eyebrow dark">LACAK PERMOHONAN</span><h2 class="modal-title">Permohonan Anda</h2><p class="modal-copy">Status diambil langsung dari SIM RT/RW–SID.</p><div class="tracking-list">${rows.length?rows.map(r=>`<div class="tracking-row"><strong>${r.service_type}</strong><span>${r.status}</span><small>${new Date(r.created_at).toLocaleString("id-ID")} · ${r.request_number||r.id}</small></div>`).join(""):"<div class='modal-note'>Belum ada permohonan.</div>"}</div>`)}catch(x){showToast("Gagal memuat status: "+(x?.message||"kesalahan"))}}
function publicDashboard(){openModal(`<span class="eyebrow dark">TRANSPARANSI & INFORMASI</span><h2 class="modal-title">Dashboard Publik <em>Desa Cerdas.</em></h2><p class="modal-copy">Ringkasan data publik yang aman ditampilkan. Pilih konteks untuk melihat indikator, penjelasan, dan batas data yang digunakan.</p><div class="dashboard-summary"><div><small>DATA PUBLIK</small><strong>Terpilih</strong><span>Agregat & terkurasi</span></div><div><small>CAKUPAN</small><strong>Desa</strong><span>RT · RW · Desa</span></div><div><small>PRIVASI</small><strong>Terjaga</strong><span>Tanpa identitas personal</span></div></div><div class="dashboard-menu"><button class="dashboard-menu-item selected" data-dashboard-tab="demography"><i class="bi bi-people"></i><span><strong>Demografi</strong><small>Penduduk & keluarga secara agregat</small></span><i class="bi bi-arrow-right"></i></button><button class="dashboard-menu-item" data-dashboard-tab="development"><i class="bi bi-building"></i><span><strong>Pembangunan Desa</strong><small>Program, progres, dan indikator pembangunan</small></span><i class="bi bi-arrow-right"></i></button><button class="dashboard-menu-item" data-dashboard-tab="services"><i class="bi bi-clipboard-check"></i><span><strong>Layanan Publik</strong><small>Aktivitas pelayanan secara agregat</small></span><i class="bi bi-arrow-right"></i></button><button class="dashboard-menu-item" data-dashboard-tab="economy"><i class="bi bi-shop"></i><span><strong>Ekonomi Desa</strong><small>Usaha, sektor, produk, dan potensi lokal</small></span><i class="bi bi-arrow-right"></i></button><button class="dashboard-menu-item" data-dashboard-tab="agenda"><i class="bi bi-calendar-event"></i><span><strong>Agenda & Kegiatan</strong><small>Kegiatan publik yang diterbitkan desa</small></span><i class="bi bi-arrow-right"></i></button><button class="dashboard-menu-item" data-dashboard-tab="gis"><i class="bi bi-map"></i><span><strong>Wilayah & GIS</strong><small>Konteks ruang dan fasilitas publik</small></span><i class="bi bi-arrow-right"></i></button><button class="dashboard-menu-item" data-dashboard-tab="method"><i class="bi bi-database-check"></i><span><strong>Sumber & Metodologi</strong><small>Asal, periode, klasifikasi, dan batas data</small></span><i class="bi bi-arrow-right"></i></button></div><div id="dashboardDetail" class="dashboard-detail"><div class="modal-note">Memuat indikator publik…</div></div><div class="modal-cta submenu-actions"><button class="btn btn-outline-civic" data-menu-main>Menu utama</button><button class="btn btn-outline-civic" data-home>Home</button></div>`);loadDashboardTab("demography")}
function renderGoogleMap(coords){const box=document.getElementById("publicGoogleMap");if(!box)return;const lat=coords?.latitude,lng=coords?.longitude;const q=lat!=null&&lng!=null?lat+","+lng:"Cinere, Depok, Jawa Barat";const label=lat!=null&&lng!=null?"Lokasi perangkat yang dibagikan":"Peta konteks publik";const mapsUrl="https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(q);box.innerHTML='<iframe title="Google Maps — '+label+'" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q='+encodeURIComponent(q)+'&output=embed"></iframe><div class="gis-map-caption"><i class="bi bi-geo-alt"></i><span><strong>'+label+'</strong><small>'+((lat!=null&&lng!=null)?"Lokasi hanya ditampilkan setelah warga memberi izin berbagi lokasi. Koordinat memiliki batas akurasi sesuai perangkat.":"Peta Google Maps digunakan sebagai konteks lokasi. Layer desa, RT/RW, dan fasilitas hanya ditampilkan setelah data GIS publik diterbitkan.")+'</small></span><a href="'+mapsUrl+'" target="_blank" rel="noopener" class="btn btn-outline-civic btn-sm">Buka Google Maps</a></div>'}
async function shareEmergencyLocation(){const status=document.getElementById("emergencyLocationStatus");if(!status)return;const u=await currentUser();if(!u){loginRequired();return}if(!navigator.geolocation){status.textContent="Perangkat/browser ini tidak menyediakan layanan lokasi.";return}status.textContent="Meminta izin lokasi dari perangkat…";navigator.geolocation.getCurrentPosition(async pos=>{try{const duration=Number(document.getElementById("emergencyDuration")?.value||30);const reason=document.getElementById("emergencyReason")?.value||"";const coords={latitude:pos.coords.latitude,longitude:pos.coords.longitude};renderGoogleMap(coords);const r=await sb.functions.invoke("citizen-location",{body:{action:"share",territory_id:territoryForArea(),latitude:coords.latitude,longitude:coords.longitude,accuracy_m:pos.coords.accuracy,duration_minutes:duration,reason}});if(r.error||!r.data?.ok)throw new Error(r.data?.error||r.error?.message||"Gagal membagikan lokasi");status.textContent="✓ Lokasi darurat tersimpan sampai "+new Date(r.data.event.expires_at).toLocaleTimeString("id-ID",{hour:"2-digit",minute:"2-digit"});showToast("✓ Lokasi darurat dibagikan");}catch(e){status.textContent=e?.message||"Gagal membagikan lokasi"}},err=>{status.textContent=err.code===1?"Izin lokasi ditolak. Anda dapat mengubah izin lokasi pada browser.":"Lokasi tidak dapat diperoleh: "+(err.message||"perangkat tidak tersedia")},{enableHighAccuracy:true,timeout:10000,maximumAge:0})}
function emergencyLocationPanel(){return '<div class="emergency-location-panel"><span class="eyebrow dark">BANTUAN DARURAT</span><strong>Bagikan lokasi saya</strong><p>Lokasi hanya dibaca setelah Anda menekan tombol dan memberi izin browser. Lokasi aktif disimpan sementara untuk koordinasi keadaan darurat dan otomatis kedaluwarsa.</p><div class="emergency-location-fields"><label>Durasi<select id="emergencyDuration"><option value="15">15 menit</option><option value="30" selected>30 menit</option><option value="60">60 menit</option></select></label><label>Keadaan darurat / keterangan<input id="emergencyReason" maxlength="500" placeholder="Contoh: kecelakaan, banjir, perlu bantuan"></label></div><button class="btn btn-civic" type="button" data-share-emergency><i class="bi bi-crosshair"></i> Bagikan lokasi darurat</button><small id="emergencyLocationStatus" class="emergency-location-status">Tidak aktif. Lokasi tidak dibaca otomatis.</small></div>'}
function dashboardContextForms(tab){const data={demography:[["Penduduk","Jumlah penduduk, kelompok usia, jenis kelamin, dan tren periode."],["Keluarga","Jumlah keluarga, komposisi rumah tangga, dan sebaran agregat."],["Pendidikan","Komposisi jenjang pendidikan dan indikator pendidikan warga."],["Pekerjaan","Kelompok pekerjaan, sektor mata pencaharian, dan indikator tenaga kerja."]],development:[["Program Desa","Daftar program publik, tujuan, lokasi, dan periode."],["Progres","Target, realisasi, persentase progres, dan status program."],["Indikator","Indikator pembangunan yang telah ditetapkan untuk publikasi."],["Peta Pembangunan","Lokasi program dan konteks wilayah secara agregat."]],services:[["Permohonan","Jumlah permohonan layanan berdasarkan periode dan kategori."],["Status Layanan","Distribusi layanan: masuk, diproses, selesai, dan lainnya."],["Jenis Layanan","Perbandingan kategori layanan publik."],["Kinerja","Ringkasan waktu/status pelayanan yang aman dipublikasikan."]],economy:[["Profil Usaha","Direktori usaha yang sudah berstatus public_visible."],["Sektor","Distribusi sektor usaha lokal."],["Produk & Jasa","Kelompok produk dan jasa yang dipublikasikan."],["Potensi Lokal","Potensi, kebutuhan, dan pengembangan ekonomi desa."]],agenda:[["Kalender","Agenda publik berdasarkan tanggal dan periode."],["Kegiatan RT/RW","Kegiatan yang diterbitkan pada konteks RT/RW."],["Kegiatan Desa","Agenda dan kegiatan tingkat desa."],["Partisipasi","Informasi partisipasi warga yang memang dinyatakan publik."]],gis:[["Peta Desa","Peta dasar dan konteks wilayah publik."],["RT & RW","Konteks batas/area RT dan RW setelah layer publik tersedia."],["Fasilitas Publik","Titik fasilitas, layanan, dan tempat publik."],["Layer Tematik","Pembangunan, kegiatan, dan ekonomi pada layer publik."]],method:[["Sumber Data","Asal dataset dan kanal publikasinya."],["Periode Data","Tanggal/periode referensi setiap indikator."],["Klasifikasi","Kategori publik, agregat, terbatas, dan data yang dikecualikan."],["Metodologi","Cara agregasi, pembaruan, dan batas interpretasi."]]}[tab]||[];return '<div class="dashboard-context-head"><span class="eyebrow dark">PILIH KONTEKS</span><strong>Detail '+({demography:"Demografi",development:"Pembangunan Desa",services:"Layanan Publik",economy:"Ekonomi Desa",agenda:"Agenda & Kegiatan",gis:"Wilayah & GIS",method:"Sumber & Metodologi"}[tab]||"Publik")+'</strong><small>Pilih sub-konteks untuk membuka informasi yang relevan.</small></div><div class="dashboard-context-grid">'+data.map((x,i)=>'<button class="dashboard-context-item" data-dashboard-context="'+tab+'" data-context-index="'+i+'"><span><strong>'+x[0]+'</strong><small>'+x[1]+'</small></span><i class="bi bi-arrow-right"></i></button>').join("")+'</div><div id="dashboardContextDetail" class="dashboard-context-detail"><div class="modal-note">Pilih salah satu konteks di atas.</div></div><div class="modal-cta" style="margin-top:1rem"><button class="btn btn-civic" data-emergency-command><i class="bi bi-shield-exclamation"></i> Emergency Command Center</button></div>'}
function emergencyCommandWorkspace(cases,events,notifications,roles){
  const now=Date.now();
  const role=roles?.includes("PLATFORM_ADMIN")?"PLATFORM_ADMIN":(roles?.[0]||"");
  const statusLabel=s=>s==="OPEN"?"OPEN":s==="ACKNOWLEDGED"?"ACK":s==="RESPONDING"?"RESPOND":"DONE";
  const caseCards=cases.length?cases.map(x=>{
    const left=x.sla_due_at?Math.max(0,new Date(x.sla_due_at).getTime()-now):0;
    const mins=Math.floor(left/60000),secs=Math.floor((left%60000)/1000);
    const code="EMG-"+String(x.location_event_id||"").slice(0,8).toUpperCase();
    let actions="";
    if(x.status==="OPEN"&&(role==="RT_OPERATOR"||role==="PLATFORM_ADMIN")) actions+='<button class="btn btn-civic" data-emergency-transition="acknowledge" data-location-event="'+x.location_event_id+'">ACK</button>';
    if(x.status==="ACKNOWLEDGED"&&(role==="RW_REVIEWER"||role==="PLATFORM_ADMIN")) actions+='<button class="btn btn-civic" data-emergency-transition="respond" data-location-event="'+x.location_event_id+'">RESPOND</button>';
    if(x.status==="RESPONDING"&&(role==="VILLAGE_VALIDATOR"||role==="PLATFORM_ADMIN")) actions+='<button class="btn btn-civic" data-emergency-transition="resolve" data-location-event="'+x.location_event_id+'">RESOLVE</button>';
    if(["OPEN","ACKNOWLEDGED"].includes(x.status)) actions+='<button class="btn btn-outline-civic" data-emergency-transition="cancel" data-location-event="'+x.location_event_id+'">CANCEL</button>';
    return '<div class="dashboard-context-item emergency-case-card"><span><strong>'+code+' · '+statusLabel(x.status)+'</strong><small>'+x.priority+' · '+(left?mins+'m '+secs+'s tersisa':(x.status==="OPEN"?"SLA terlewati":"SLA selesai"))+' · escalation '+x.escalation_level+'</small></span><div class="submenu-actions">'+actions+'</div></div>';
  }).join(""):"<div class='modal-note'>Tidak ada kasus aktif.</div>";
  const inbox=notifications.length?notifications.map(n=>'<div class="tracking-row"><strong>'+n.title+'</strong><span>'+n.target_role+' · '+n.status+'</span><small>'+n.body+'</small><small>'+new Date(n.created_at).toLocaleString("id-ID")+'</small></div>').join(""):"<div class='modal-note'>Inbox notifikasi kosong.</div>";
  return '<div class="emergency-command"><span class="eyebrow dark">EMERGENCY COMMAND CENTER</span><h3>Koordinasi respons darurat</h3><p class="modal-copy">Inbox dan tindakan hanya menampilkan kasus sesuai role dan scope Anda.</p><div class="modal-cta"><button class="btn btn-outline-civic" data-emergency-refresh><i class="bi bi-arrow-clockwise"></i> Refresh</button><button class="btn btn-civic" data-emergency-report><i class="bi bi-clipboard-data"></i> Audit & Report</button></div><h4>Kasus</h4><div class="dashboard-context-grid">'+caseCards+'</div><h4 class="mt-4">Notification Inbox</h4><div class="tracking-list">'+inbox+'</div><div class="modal-note mt-3">Timeline tersimpan: '+events.length+' event · Notifikasi: '+notifications.length+'</div></div>';
}
function emergencyAuditWorkspace(report){
  const s=report?.summary||{},n=s.notification_counts||{};
  const cards=[["Total kasus",s.total_cases??0],["OPEN",s.OPEN??0],["ACKNOWLEDGED",s.ACKNOWLEDGED??0],["RESPONDING",s.RESPONDING??0],["RESOLVED",s.RESOLVED??0],["CANCELLED",s.CANCELLED??0],["SLA breached",s.sla_breaches??0],["Escalated",s.escalated_cases??0],["Rata-rata ACK",(s.avg_ack_minutes??0)+" menit"],["Rata-rata selesai",(s.avg_resolution_minutes??0)+" menit"]];
  const timeline=(report.timeline||[]).map(x=>'<div class="tracking-row"><strong>'+x.case_code+' · '+x.status+'</strong><span>'+new Date(x.created_at).toLocaleString("id-ID")+'</span><small>'+(x.note||"Event emergency")+'</small></div>').join("")||"<div class='modal-note'>Belum ada event audit.</div>";
  return '<div class="emergency-command"><span class="eyebrow dark">EMERGENCY AUDIT & REPORTING</span><h3>Audit operasional respons darurat</h3><p class="modal-copy">Ringkasan dibatasi oleh role dan scope akun. Identitas warga dan actor ID tidak ditampilkan.</p><div class="dashboard-context-grid">'+cards.map(x=>'<div class="dashboard-context-item"><span><strong>'+x[0]+'</strong><small>'+x[1]+'</small></span></div>').join("")+'</div><h4 class="mt-4">Notification Audit</h4><div class="dashboard-context-grid"><div class="dashboard-context-item"><span><strong>PENDING</strong><small>'+(n.PENDING||0)+'</small></span></div><div class="dashboard-context-item"><span><strong>DELIVERED</strong><small>'+(n.DELIVERED||0)+'</small></span></div><div class="dashboard-context-item"><span><strong>READ</strong><small>'+(n.READ||0)+'</small></span></div><div class="dashboard-context-item"><span><strong>DISMISSED</strong><small>'+(n.DISMISSED||0)+'</small></span></div></div><h4 class="mt-4">Audit Timeline</h4><div class="tracking-list">'+timeline+'</div><div class="modal-cta mt-3"><button class="btn btn-outline-civic" data-emergency-refresh><i class="bi bi-arrow-left"></i> Kembali ke Command Center</button></div></div>';
}
